@php($seoBudgets=\App\Models\SeoBudget::where('workspace_id',$workspace->id)->where('month',now('UTC')->format('Y-m'))->get())
<div class="card p-5 mb-6"><h2 class="font-semibold">SEO API maliyet kontrolü</h2><p class="subtitle">Varsayılan aylık limit ${{ number_format(config('seo.monthly_budget_micros')/1000000,2) }}. MOCK raporlanan maliyetler simülasyondur ve gerçek maliyete eklenmez. Cache okuması yeni ücret üretmez.</p>@foreach($seoBudgets as $budget)<p class="text-sm mt-3">{{ strtoupper($budget->mode) }} · ${{ number_format($budget->spent_micros/1000000,6) }} / ${{ number_format($budget->limit_micros/1000000,2) }} · Bekleyen rezervasyon ${{ number_format($budget->held_micros/1000000,6) }} · {{ $budget->blocked?'İnceleme gerekli':'Açık' }}</p>@endforeach
@php($receipts=$workspace->apiUsageLogs()->whereNotNull('mode')->latest('id')->limit(30)->get())
<div class="overflow-x-auto mt-4"><table class="w-full text-xs text-left"><thead><tr><th class="p-2">İstek</th><th class="p-2">Mod</th><th class="p-2">Durum / kod</th><th class="p-2">Raporlanan USD</th><th class="p-2">Gerçek USD</th><th class="p-2">Rezervasyon USD</th></tr></thead><tbody>@foreach($receipts as $receipt)<tr class="border-t border-slate-100"><td class="p-2">{{ $receipt->operation }}</td><td class="p-2">{{ $receipt->mode }}</td><td class="p-2">{{ $receipt->status }} / {{ $receipt->provider_status ?? $receipt->error_code ?? '—' }}</td><td class="p-2">{{ $receipt->reported_cost_micros === null ? 'Bilinmiyor' : number_format($receipt->reported_cost_micros/1000000,6) }}</td><td class="p-2">{{ $receipt->status==='uncertain'?'Bilinmiyor':$receipt->cost }}</td><td class="p-2">{{ in_array($receipt->status,['pending','uncertain'])?number_format($receipt->reserved_micros/1000000,6):'0.000000' }}</td></tr>@endforeach</tbody></table></div></div>
